  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["SW6", "R34", "R35"],
      "pins": ["SW6.1", "SW6.2", "SW6.3", "SW6.4", "R34.1", "R34.2", "R35.1", "R35.2"],
      "nets": ["/CAN0_N", "/CAN0_P", "/CAN1_N", "/CAN1_P", "Net-(R34-Pad2)", "Net-(R35-Pad2)"],
      "observed": "The two 120R termination resistors connect from CAN0_N and CAN1_N to separate switch nets. SW6.1–2 joins those resistor ends, while SW6.3–4 joins CAN1_P to CAN0_P; neither resistor is switched across its own CAN bus's P/N pair.",
      "expected": "Each CAN bus should remain independent, with its termination resistor switched across that bus's CAN_P and CAN_N lines.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"/CAN0_N\") ... (node (ref \"R34\") (pin \"1\")) ...)"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/CAN0_P\") ... (node (ref \"SW6\") (pin \"4\")) ...)"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/CAN1_N\") ... (node (ref \"R35\") (pin \"1\")) ...)"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/CAN1_P\") ... (node (ref \"SW6\") (pin \"3\")) ...)"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"Net-(R34-Pad2)\") ... (node (ref \"SW6\") (pin \"1\"))) ; (net (name \"Net-(R35-Pad2)\") ... (node (ref \"SW6\") (pin \"2\")))"
        },
        {
          "source": "spec",
          "quote": "two isolated CAN buses (CAN0, CAN1), each driven by its own MCP2515 SPI CAN controller"
        }
      ],
      "impact": "The termination switches cannot correctly terminate each bus independently. Depending on switch settings, they can instead tie the two CAN_P lines together and/or connect the two CAN_N lines through the 120R resistors, disrupting bus signaling and isolation between the CAN channels.",
      "confidence": 0.91
    }
  ],
  "summary": "Anomaly detected: SW6 and the two 120R resistors are connected so they do not terminate CAN0 and CAN1 across their respective P/N pairs. The switch arrangement can instead couple the two bus channels."
}

